#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# Rules under test:
#   1. bin/claude forces --dangerously-skip-permissions, once, even when the
#      caller already passed it, and still forwards the caller's args.
#   2. bin/claude adds headless=true for -p/--print and leaves existing
#      OTEL_RESOURCE_ATTRIBUTES intact.
#   3. bin/codex forces --no-daemon and both bypass flags, keeps an inherited
#      `project` from OTEL_RESOURCE_ATTRIBUTES, appends the launch directory
#      only when none is inherited, and writes stderr to CODEX_ERROR_LOG while
#      preserving the exit status.
#   4. bin/opencode forces --auto, forwards its args, and resolves the native
#      CLI by absolute path, so a shim cannot exec itself.
#
# The native binaries are a fake reached through CLAUDE_CMD/CODEX_CMD/
# OPENCODE_CMD, so the checks do not need any agent installed.
#
# Run: tests/test-agent-shims.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "${SCRIPT_DIR}/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

fail() { echo "FAIL: $1" >&2; exit 1; }

FAKE="${TMP}/fake-agent"
cat > "$FAKE" << 'FAKEEOF'
#!/bin/bash
printf '%s\n' "$@" > "${AGENT_LOG}.args"
printf '%s\n' "${OTEL_RESOURCE_ATTRIBUTES:-<unset>}" > "${AGENT_LOG}.attrs"
printf '%s\n' "${CODEX_PROJECT:-<unset>}" > "${AGENT_LOG}.project"
FAKEEOF
chmod +x "$FAKE"

args_of() { cat "$1.args"; }

# --- claude: bypass permissions is forced, exactly once, args preserved ---
env -u OTEL_RESOURCE_ATTRIBUTES CLAUDE_CMD="$FAKE" AGENT_LOG="${TMP}/c1" \
    "${REPO_ROOT}/bin/claude" -c
[[ "$(args_of "${TMP}/c1")" == $'--dangerously-skip-permissions\n-c' ]] \
    || fail "claude did not force --dangerously-skip-permissions: $(args_of "${TMP}/c1")"

env -u OTEL_RESOURCE_ATTRIBUTES CLAUDE_CMD="$FAKE" AGENT_LOG="${TMP}/c2" \
    "${REPO_ROOT}/bin/claude" --dangerously-skip-permissions -c
[[ "$(grep -c -- '--dangerously-skip-permissions' "${TMP}/c2.args")" == "1" ]] \
    || fail "claude duplicated --dangerously-skip-permissions"

env OTEL_RESOURCE_ATTRIBUTES="host.name=machine" CLAUDE_CMD="$FAKE" AGENT_LOG="${TMP}/c3" \
    "${REPO_ROOT}/bin/claude" -p
[[ "$(cat "${TMP}/c3.attrs")" == "host.name=machine,headless=true" ]] \
    || fail "claude headless tag did not append to existing attributes: $(cat "${TMP}/c3.attrs")"

# --- codex: no inherited project means the launch directory ---
mkdir -p "${TMP}/cwd"
( cd "${TMP}/cwd" && env -u OTEL_RESOURCE_ATTRIBUTES CODEX_CMD="$FAKE" AGENT_LOG="${TMP}/x1" \
    "${REPO_ROOT}/bin/codex" --version )
[[ "$(args_of "${TMP}/x1")" == $'--no-daemon\n--dangerously-bypass-approvals-and-sandbox\n--dangerously-bypass-hook-trust\n--version' ]] \
    || fail "codex did not force its bypass flags: $(args_of "${TMP}/x1")"
[[ "$(cat "${TMP}/x1.project")" == "${TMP}/cwd" ]] \
    || fail "codex did not use the launch directory as project: $(cat "${TMP}/x1.project")"
[[ "$(cat "${TMP}/x1.attrs")" == "project=${TMP}/cwd" ]] \
    || fail "codex did not append project: $(cat "${TMP}/x1.attrs")"

# --- codex: an inherited project wins and is not duplicated ---
( cd "${TMP}/cwd" && env OTEL_RESOURCE_ATTRIBUTES="host.name=machine,project=/host/sandbox" \
    CODEX_CMD="$FAKE" AGENT_LOG="${TMP}/x2" "${REPO_ROOT}/bin/codex" )
[[ "$(cat "${TMP}/x2.project")" == "/host/sandbox" ]] \
    || fail "codex did not inherit project: $(cat "${TMP}/x2.project")"
[[ "$(cat "${TMP}/x2.attrs")" == "host.name=machine,project=/host/sandbox" ]] \
    || fail "codex rewrote inherited attributes: $(cat "${TMP}/x2.attrs")"

# --- codex: bypass flags the caller already passed are not duplicated ---
env -u OTEL_RESOURCE_ATTRIBUTES CODEX_CMD="$FAKE" AGENT_LOG="${TMP}/x3" \
    "${REPO_ROOT}/bin/codex" --dangerously-bypass-hook-trust
[[ "$(grep -c -- '--dangerously-bypass-hook-trust' "${TMP}/x3.args")" == "1" ]] \
    || fail "codex duplicated --dangerously-bypass-hook-trust"

# --- codex: startup stderr survives for harness-wrapper.sh, status intact ---
FAILING="${TMP}/failing-codex"
printf '#!/bin/bash\necho "refresh token was revoked" >&2\nexit 7\n' > "$FAILING"
chmod +x "$FAILING"
status=0
env -u OTEL_RESOURCE_ATTRIBUTES CODEX_CMD="$FAILING" CODEX_ERROR_LOG="${TMP}/codex-err.log" \
    "${REPO_ROOT}/bin/codex" >/dev/null 2>&1 || status=$?
[[ "$status" == "7" ]] || fail "codex lost the native exit status (got ${status})"
grep -q 'refresh token was revoked' "${TMP}/codex-err.log" \
    || fail "codex did not save startup stderr to CODEX_ERROR_LOG"

# --- opencode: --auto is forced, once, and args pass through ---
env OPENCODE_CMD="$FAKE" AGENT_LOG="${TMP}/o1" "${REPO_ROOT}/bin/opencode" --continue
[[ "$(args_of "${TMP}/o1")" == $'--auto\n--continue' ]] \
    || fail "opencode did not force --auto: $(args_of "${TMP}/o1")"

env OPENCODE_CMD="$FAKE" AGENT_LOG="${TMP}/o2" "${REPO_ROOT}/bin/opencode" --auto --continue
[[ "$(grep -c -- '--auto' "${TMP}/o2.args")" == "1" ]] \
    || fail "opencode duplicated --auto"

status=0
env OPENCODE_CMD="opencode" "${REPO_ROOT}/bin/opencode" >/dev/null 2>&1 || status=$?
[[ "$status" == "127" ]] || fail "opencode accepted a relative OPENCODE_CMD (exit ${status})"

echo "all agent-shim checks passed"
